command:
/**
 * 宏: 随机物品 (排除武学/内功)
 * 逻辑: 自动过滤空分类，确保必出物品，且【仅抽取官方资源】
 */
const browser = game.xjzl.compendiumBrowser;
if (!browser.isLoaded) await browser.loadData();

// === ⚙️ 配置区域 ===
const config = {
    amount: 1,
    weighted: true,
    alias: "物品宝盒",
    title: "随机宝物",
    customWeights: { 0: 100, 1: 60, 2: 30, 3: 10, 4: 2 }
};
// ==================

const candidates =["weapon", "armor", "consumable", "misc", "qizhen", "art_book"];
const validTabs = candidates.filter(t => browser.cachedData[t] && browser.cachedData[t].length > 0);
if (validTabs.length === 0) return ui.notifications.warn("当前世界中没有可用的物品数据！");

const randomTab = validTabs[Math.floor(Math.random() * validTabs.length)];

const items = await browser.randomize({
    tab: randomTab,
    amount: config.amount,
    weighted: config.weighted,
    customWeights: config.customWeights,
    filters: { isOfficial: new Set(["true"]) } // 🔒 核心：过滤掉非官方资源
});

if (items.length > 0) {
    let finalTitle = config.title;
    if (randomTab === "weapon") finalTitle = "神兵利器";
    if (randomTab === "qizhen") finalTitle = "稀世奇珍";

    browser._generateLootChatCard(items, { alias: config.alias, title: finalTitle });
} else {
    ui.notifications.warn(`该分类[${randomTab}] 下无数据。`);
}

/**
 * 宏: 随机秘籍
 * 逻辑: 在武学和内功中随机，且【仅抽取官方资源】
 */
const browser = game.xjzl.compendiumBrowser;
if (!browser.isLoaded) await browser.loadData();

const config = {
    amount: 1,
    weighted: true,
    alias: "武学宝盒",
    customWeights: { 1: 100, 2: 20, 3: 5 }
};

const candidates = ["wuxue", "neigong"];
const validTabs = candidates.filter(t => browser.cachedData[t] && browser.cachedData[t].length > 0);
if (validTabs.length === 0) return ui.notifications.warn("未录入武学或内功！");

const randomTab = validTabs[Math.floor(Math.random() * validTabs.length)];

const items = await browser.randomize({
    tab: randomTab,
    amount: config.amount,
    weighted: config.weighted,
    customWeights: config.customWeights,
    filters: { isOfficial: new Set(["true"]) } // 🔒 核心：过滤掉非官方资源
});

if (items.length > 0) {
    browser._generateLootChatCard(items, { 
        alias: config.alias,
        title: randomTab === "neigong" ? "扩展内功心法" : "扩展武学招式"
    });
} else {
    ui.notifications.warn(`该分类 [${randomTab}] 下无数据。`);
}

/**
 * 宏: 全池随机
 * 逻辑: 包含所有类型，【仅抽取官方资源】
 */
const browser = game.xjzl.compendiumBrowser;
if (!browser.isLoaded) await browser.loadData();

const config = {
    amount: 1,
    weighted: true,
    alias: "江湖奇遇",
    qualityWeights: { 0: 100, 1: 60, 2: 30, 3: 10, 4: 2 },
    tierWeights: { 1: 100, 2: 20, 3: 5 }
};

const candidates =["weapon", "armor", "consumable", "misc", "qizhen", "art_book", "wuxue", "neigong"];
const validTabs = candidates.filter(t => browser.cachedData[t] && browser.cachedData[t].length > 0);
if (validTabs.length === 0) return ui.notifications.warn("没有任何物品数据！");

const randomTab = validTabs[Math.floor(Math.random() * validTabs.length)];

let selectedWeights = config.qualityWeights;
if (["wuxue", "neigong"].includes(randomTab)) selectedWeights = config.tierWeights;

const items = await browser.randomize({
    tab: randomTab,
    amount: config.amount,
    weighted: config.weighted,
    customWeights: selectedWeights,
    filters: { isOfficial: new Set(["true"]) } // 🔒 核心：过滤掉非官方资源
});

if (items.length > 0) {
    let finalTitle = "随机宝物";
    if (["wuxue", "neigong"].includes(randomTab)) finalTitle = "扩展秘籍";
    else if (["weapon", "armor"].includes(randomTab)) finalTitle = "扩展装备";

    browser._generateLootChatCard(items, { alias: config.alias, title: finalTitle });
} else {
    ui.notifications.warn(`随到了 [${randomTab}] 分类，但该分类下无数据。`);
}

/**
 * 宏: 随机江湖武学
 * 逻辑: 抽取门派为 'jianghushili' 且【是官方资源】的武学/内功
 */
const browser = game.xjzl.compendiumBrowser;
if (!browser.isLoaded) await browser.loadData();

const config = {
    amount: 1,
    weighted: true,
    alias: "武学宝盒",
    targetSect: "jianghushili", 
    customWeights: { 1: 100, 2: 20, 3: 5 }
};

const candidates = ["wuxue", "neigong"];
const validTabs = candidates.filter(t => browser.cachedData[t] && browser.cachedData[t].length > 0);
if (validTabs.length === 0) return ui.notifications.warn("数据未加载或为空！");

const randomTab = validTabs[Math.floor(Math.random() * validTabs.length)];

const items = await browser.randomize({
    tab: randomTab,
    amount: config.amount,
    weighted: config.weighted,
    customWeights: config.customWeights,
    filters: {
        sect: new Set([config.targetSect]),
        isOfficial: new Set(["true"]) // 🔒 核心：组合过滤条件
    }
});

if (items.length > 0) {
    browser._generateLootChatCard(items, { 
        alias: config.alias,
        title: randomTab === "neigong" ? "江湖心法" : "江湖招式"
    });
} else {
    ui.notifications.warn(`未找到属于 [${config.targetSect}] 的秘籍。`);
}

/**
 * 宏: 必出天级武学/内功
 * 逻辑: 纯随机（无权重，因为全是一样的天级），限定品阶为3
 */
const browser = game.xjzl.compendiumBrowser;
if (!browser.isLoaded) await browser.loadData();

const candidates =["wuxue", "neigong"];
const randomTab = candidates[Math.floor(Math.random() * candidates.length)];

const items = await browser.randomize({
    tab: randomTab,
    amount: 1,
    weighted: false, // 既然锁定天阶了，就不需要走权重算法了
    filters: { 
        tier: new Set(["3"]) // 🔒 核心：锁定天级 (3)
    }
});

if (items.length > 0) {
    browser._generateLootChatCard(items, { alias: "隐世高人", title: "天阶绝学" });
} else {
    ui.notifications.warn("当前合集包中没有天级秘籍！");
}
